declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  if public.has_org_role(
    p_session.organization_id,
    array['owner','admin','manager']::public.member_role[]
  ) then
    return v_uid; -- supervisor override
  end if;

  if public.has_org_role(
    p_session.organization_id,
    array['operator']::public.member_role[]
  ) then
    if p_session.cashier_id is distinct from v_uid then
      raise exception 'POS operator may only act on own cashier session (cashier_id ownership)';
    end if;
    return v_uid;
  end if;

  raise exception 'insufficient role for POS session action %', p_action;
end;

