declare
  v_uid uuid;
  v_pack public.module_packs%rowtype;
  v_items jsonb := '[]'::jsonb;
  r record;
  v_class text;
begin
  v_uid := public.modules_assert_configure(p_organization_id);
  select * into v_pack from public.module_packs where id = p_pack_id and active;
  if not found then raise exception 'PACK_NOT_FOUND'; end if;

  for r in
    select
      c.code,
      c.name,
      mpf.recommended_enabled,
      rc.release_status,
      e.status as entitlement_status,
      coalesce(ofe.status::text, 'disabled') as effective_status
    from public.module_pack_features mpf
    join public.feature_catalog c on c.id = mpf.feature_id
    left join public.feature_release_controls rc on rc.feature_id = c.id
    left join public.organization_feature_entitlements e
      on e.organization_id = p_organization_id and e.feature_id = c.id
    left join public.organization_features ofe
      on ofe.organization_id = p_organization_id and ofe.feature_id = c.id
    where mpf.pack_id = p_pack_id
    order by mpf.sort_order, c.code
  loop
    if r.release_status = 'COMING_SOON'::public.feature_release_status then
      v_class := 'coming_soon';
    elsif r.release_status = 'RESTRICTED'::public.feature_release_status
         or r.entitlement_status = 'RESTRICTED'::public.feature_entitlement_status then
      v_class := 'restricted';
    elsif r.release_status in (
      'BLOCKED'::public.feature_release_status,
      'RETIRED'::public.feature_release_status
    ) then
      v_class := 'release_blocked';
    elsif r.entitlement_status is distinct from 'GRANTED'::public.feature_entitlement_status then
      v_class := 'not_entitled';
    elsif r.effective_status = 'enabled' then
      v_class := 'already_enabled';
    else
      v_class := 'available';
    end if;

    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'feature_code', r.code,
      'name', r.name,
      'classification', v_class,
      'recommended_enabled', r.recommended_enabled
    ));
  end loop;

  return jsonb_build_object(
    'pack_id', p_pack_id,
    'pack_code', v_pack.code,
    'pack_name', v_pack.name,
    'configuration_before_hash', public.modules_config_hash(p_organization_id),
    'items', v_items,
    'generated_by', v_uid
  );
end;

declare v_ok boolean;
begin
  select exists (
    select 1
    from public.organization_features ofeat
    join public.feature_catalog fc on fc.id = ofeat.feature_id
    where ofeat.organization_id = p_org_id
      and fc.code = 'purchases'
      and ofeat.status = 'enabled'
  ) into v_ok;
  if not coalesce(v_ok, false) then
    raise exception 'purchases feature is not enabled for this organization';
  end if;
end;

begin
  if not public.has_org_role(p_org_id, p_roles) then
    raise exception 'insufficient role for purchase operation';
  end if;
end;

declare
  v_type public.product_type;
  v_clearing uuid;
begin
  if p_product_id is null then
    return p_fallback_expense;
  end if;
  select product_type into v_type
  from public.products
  where id = p_product_id and organization_id = p_organization_id;
  if v_type is distinct from 'STOCK_ITEM' then
    return p_fallback_expense;
  end if;
  select inventory_purchase_clearing_account_id into v_clearing
  from public.inventory_accounting_mappings
  where organization_id = p_organization_id;
  if v_clearing is null then
    raise exception 'STOCK_ITEM line requires inventory purchase clearing mapping';
  end if;
  return v_clearing;
end;

declare
  v_subtotal numeric(19, 4);
  v_discount numeric(19, 4);
begin
  v_subtotal := round(new.quantity * new.unit_price, 4);

  if new.discount_input_mode = 'PERCENT' then
    if new.discount_percent < 0 or new.discount_percent > 100 then
      raise exception 'invalid discount percent';
    end if;
    v_discount := round(v_subtotal * new.discount_percent / 100, 4);
    new.discount_amount := v_discount;
  else
    v_discount := round(new.discount_amount, 4);
    if v_discount < 0 then
      raise exception 'discount amount cannot be negative';
    end if;
    if v_discount > v_subtotal then
      raise exception 'discount cannot exceed line subtotal';
    end if;
    if v_subtotal > 0 then
      new.discount_percent := round(v_discount / v_subtotal * 100, 4);
    else
      new.discount_percent := 0;
    end if;
  end if;

  new.line_subtotal := v_subtotal;
  new.line_total := round(v_subtotal - v_discount, 4);
  if new.line_total < 0 then
    raise exception 'line total cannot be negative';
  end if;
  return new;
end;

declare
  v_org uuid;
  v_n int := 0;
begin
  perform public.modules_assert_service_role();
  for v_org in select id from public.organizations order by created_at loop
    perform public.recompute_organization_features(v_org, p_actor, p_source);
    v_n := v_n + 1;
  end loop;
  return jsonb_build_object('organizations_recomputed', v_n, 'feature_id', p_feature_id);
end;

declare
  v_feat record;
  v_eval jsonb;
  v_new_status public.feature_status;
  v_old_status public.feature_status;
  v_had boolean;
  v_changed int := 0;
  v_pass_changed int;
  v_pass int;
  v_engine text;
  v_quiet boolean;
begin
  perform public.modules_lock_organization(p_organization_id);
  v_engine := current_setting('modules.engine_write', true);
  perform set_config('modules.engine_write', '1', true);
  v_quiet := coalesce(current_setting('modules.migration_quiet', true), '') = '1';

  for v_pass in 1..8 loop
    v_pass_changed := 0;
    for v_feat in
      select c.id, c.code
      from public.feature_catalog c
      where c.active
      order by c.sort_order, c.code
    loop
      v_eval := public.modules_evaluate_feature_state(p_organization_id, v_feat.id);
      v_new_status := (v_eval->>'status')::public.feature_status;

      select true, ofe.status into v_had, v_old_status
      from public.organization_features ofe
      where ofe.organization_id = p_organization_id and ofe.feature_id = v_feat.id;

      if v_quiet and coalesce(v_had, false) then
        update public.organization_features
        set metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
              'reason', v_eval->>'reason',
              'source', p_source,
              'evaluated_status', v_new_status
            )
        where organization_id = p_organization_id and feature_id = v_feat.id;
        continue;
      end if;

      if not coalesce(v_had, false) then
        if v_quiet then
          v_new_status := 'disabled'::public.feature_status;
        end if;
        insert into public.organization_features (
          organization_id, feature_id, status, enabled_at, metadata
        ) values (
          p_organization_id, v_feat.id, v_new_status,
          case when v_new_status = 'enabled' then timezone('utc', now()) else null end,
          jsonb_build_object('reason', v_eval->>'reason', 'source', p_source)
        );
        v_pass_changed := v_pass_changed + 1;
        if not v_quiet then
          perform public.modules_write_audit(
            p_organization_id, p_actor, 'module.effective.changed', 'create',
            jsonb_build_object(
              'feature_code', v_feat.code,
              'old_status', 'disabled',
              'new_status', v_new_status,
              'reason', v_eval->>'reason',
              'source', p_source
            )
          );
        end if;
      elsif v_old_status is distinct from v_new_status then
        update public.organization_features
        set status = v_new_status,
            enabled_at = case
              when v_new_status = 'enabled' then coalesce(enabled_at, timezone('utc', now()))
              else enabled_at
            end,
            metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
              'reason', v_eval->>'reason',
              'source', p_source
            ),
            updated_at = timezone('utc', now())
        where organization_id = p_organization_id and feature_id = v_feat.id;
        v_pass_changed := v_pass_changed + 1;
        if not v_quiet then
          perform public.modules_write_audit(
            p_organization_id, p_actor, 'module.effective.changed', 'update',
            jsonb_build_object(
              'feature_code', v_feat.code,
              'old_status', v_old_status,
              'new_status', v_new_status,
              'reason', v_eval->>'reason',
              'source', p_source
            )
          );
        end if;
      else
        update public.organization_features
        set metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
              'reason', v_eval->>'reason',
              'source', p_source
            )
        where organization_id = p_organization_id and feature_id = v_feat.id;
      end if;
    end loop;
    v_changed := v_changed + v_pass_changed;
    exit when v_pass_changed = 0 or v_quiet;
  end loop;

  if v_engine is null then
    perform set_config('modules.engine_write', '', true);
  else
    perform set_config('modules.engine_write', v_engine, true);
  end if;

  return jsonb_build_object(
    'organization_id', p_organization_id,
    'changed', v_changed,
    'hash', public.modules_config_hash(p_organization_id)
  );
end;

declare
  v_period public.tax_periods%rowtype;
  v_det public.tax_determinations%rowtype;
  v_out_acct uuid;
  v_in_acct uuid;
  v_out_bal numeric(19,4) := 0;
  v_in_bal numeric(19,4) := 0;
  v_debit numeric(19,4) := 0;
  v_credit numeric(19,4) := 0;
begin
  select * into v_period from public.tax_periods where id = p_tax_period_id;
  if not found then raise exception 'tax period not found'; end if;
  if not public.is_org_member(v_period.organization_id) then
    raise exception 'not a member';
  end if;

  select vat_output_account_id into v_out_acct
  from public.fiscal_accounting_mappings
  where organization_id = v_period.organization_id;
  select vat_input_account_id into v_in_acct
  from public.purchase_accounting_mappings
  where organization_id = v_period.organization_id;

  if v_out_acct is null or v_in_acct is null then
    return jsonb_build_object(
      'status', 'TAX_RECONCILIATION_REQUIRES_CONFIG',
      'message', 'Missing vat_output_account_id or vat_input_account_id mapping'
    );
  end if;

  select * into v_det from public.tax_determinations
  where tax_period_id = p_tax_period_id and is_current;
  if found then
    v_debit := coalesce((v_det.totals_snapshot->>'debit_fiscal')::numeric, 0);
    v_credit := coalesce((v_det.totals_snapshot->>'credit_fiscal_computable')::numeric, 0);
  end if;

  select coalesce(sum(jl.debit - jl.credit), 0) into v_out_bal
  from public.journal_entry_lines jl
  join public.journal_entries je on je.id = jl.journal_entry_id
  where jl.organization_id = v_period.organization_id
    and jl.account_id = v_out_acct
    and je.status = 'POSTED'
    and je.entry_date between v_period.period_start and v_period.period_end;

  select coalesce(sum(jl.debit - jl.credit), 0) into v_in_bal
  from public.journal_entry_lines jl
  join public.journal_entries je on je.id = jl.journal_entry_id
  where jl.organization_id = v_period.organization_id
    and jl.account_id = v_in_acct
    and je.status = 'POSTED'
    and je.entry_date between v_period.period_start and v_period.period_end;

  return jsonb_build_object(
    'status', 'OK',
    'vat_output_account_id', v_out_acct,
    'vat_input_account_id', v_in_acct,
    'workpaper_debit', v_debit,
    'ledger_vat_output_movement', v_out_bal,
    'debit_difference', v_debit - abs(v_out_bal),
    'workpaper_credit_computable', v_credit,
    'ledger_vat_input_movement', v_in_bal,
    'credit_difference', v_credit - abs(v_in_bal),
    'auto_fixed', false
  );
end;

declare
  v_uid uuid;
  v_period public.tax_periods%rowtype;
  v_prior public.tax_filing_records%rowtype;
  v_id uuid;
  v_walk uuid;
  v_guard int := 0;
begin
  select * into v_period from public.tax_periods where id = p_tax_period_id;
  if not found then raise exception 'tax period not found'; end if;
  v_uid := public.tax_assert_role(
    v_period.organization_id,
    array['owner','accountant']::public.member_role[]
  );
  perform public.tax_assert_feature(v_period.organization_id);

  if p_external_receipt_number is null or length(trim(p_external_receipt_number)) < 1 then
    raise exception 'external receipt required for FILED_EXTERNAL';
  end if;

  if p_filing_kind = 'ORIGINAL' then
    if p_supersedes_filing_id is not null then
      raise exception 'ORIGINAL filing must have supersedes_filing_id NULL';
    end if;
  elsif p_filing_kind = 'RECTIFICATION' then
    if p_supersedes_filing_id is null then
      raise exception 'rectification requires supersedes_filing_id';
    end if;
    if p_supersedes_filing_id = p_tax_period_id then
      raise exception 'invalid supersedes reference';
    end if;

    select * into v_prior
    from public.tax_filing_records
    where id = p_supersedes_filing_id
    for share;

    if not found then
      raise exception 'superseded filing not found';
    end if;
    if v_prior.organization_id is distinct from v_period.organization_id then
      raise exception 'cross-tenant filing rectification denied';
    end if;
    if v_prior.tax_period_id is distinct from v_period.id then
      raise exception 'rectification must target same tax period';
    end if;
    if v_prior.tax_code is distinct from v_period.tax_code then
      raise exception 'rectification must target same tax_code';
    end if;
    if v_prior.jurisdiction_code is distinct from v_period.jurisdiction_code then
      raise exception 'rectification must target same jurisdiction';
    end if;
    if v_prior.status is distinct from 'FILED_EXTERNAL' then
      raise exception 'can only rectify FILED_EXTERNAL evidence';
    end if;

    -- Cycle guard: walk supersedes chain
    v_walk := v_prior.supersedes_filing_id;
    while v_walk is not null loop
      v_guard := v_guard + 1;
      if v_guard > 50 then
        raise exception 'filing chain too deep / cyclic';
      end if;
      if v_walk = p_supersedes_filing_id then
        raise exception 'cyclic filing rectification chain';
      end if;
      select supersedes_filing_id into v_walk
      from public.tax_filing_records
      where id = v_walk
        and organization_id = v_period.organization_id;
    end loop;
  else
    raise exception 'unsupported filing_kind';
  end if;

  perform set_config('tax.engine_write', '1', true);
  insert into public.tax_filing_records (
    organization_id, tax_period_id, tax_code, jurisdiction_code,
    filing_kind, status, external_form_code, external_receipt_number,
    filed_at, filed_by, evidence_reference, evidence_hash, supersedes_filing_id
  ) values (
    v_period.organization_id, v_period.id, v_period.tax_code, v_period.jurisdiction_code,
    p_filing_kind, 'FILED_EXTERNAL', p_external_form_code, p_external_receipt_number,
    coalesce(p_filed_at, timezone('utc', now())), v_uid,
    p_evidence_reference, p_evidence_hash, p_supersedes_filing_id
  )
  returning id into v_id;
  return v_id;
end;

declare
  v_uid uuid;
  v_obl public.tax_obligations%rowtype;
  v_id uuid;
  v_paid numeric(19, 4);
  v_outstanding numeric(19, 4);
begin
  select * into v_obl from public.tax_obligations where id = p_tax_obligation_id for update;
  if not found then raise exception 'obligation not found'; end if;
  v_uid := public.tax_assert_role(
    v_obl.organization_id,
    array['owner','accountant']::public.member_role[]
  );
  perform public.tax_assert_feature(v_obl.organization_id);

  if p_amount is null or p_amount <= 0 then
    raise exception 'payment amount must be > 0';
  end if;
  if p_external_reference is null or length(trim(p_external_reference)) < 1 then
    raise exception 'external_reference required';
  end if;

  -- Idempotent retry: same evidence identity returns existing row
  select id into v_id
  from public.tax_payment_records
  where organization_id = v_obl.organization_id
    and tax_obligation_id = v_obl.id
    and external_reference = p_external_reference
    and payment_date = p_payment_date
    and amount = p_amount
  limit 1;
  if v_id is not null then
    return v_id;
  end if;

  select coalesce(sum(amount), 0) into v_paid
  from public.tax_payment_records
  where tax_obligation_id = v_obl.id;

  v_outstanding := v_obl.amount - v_paid;
  if v_outstanding < 0 then
    v_outstanding := 0;
  end if;

  if p_amount > v_outstanding then
    raise exception 'TAX_PAYMENT_EXCEEDS_OUTSTANDING';
  end if;

  perform set_config('tax.engine_write', '1', true);
  begin
    insert into public.tax_payment_records (
      organization_id, tax_obligation_id, payment_date, amount, external_reference,
      payment_method_description, evidence_reference, evidence_hash, recorded_by
    ) values (
      v_obl.organization_id, v_obl.id, p_payment_date, p_amount, p_external_reference,
      p_payment_method_description, p_evidence_reference, p_evidence_hash, v_uid
    )
    returning id into v_id;
  exception
    when unique_violation then
      select id into v_id
      from public.tax_payment_records
      where organization_id = v_obl.organization_id
        and tax_obligation_id = v_obl.id
        and external_reference = p_external_reference
        and payment_date = p_payment_date
        and amount = p_amount
      limit 1;
      return v_id;
  end;

  select coalesce(sum(amount), 0) into v_paid
  from public.tax_payment_records where tax_obligation_id = v_obl.id;
  v_outstanding := v_obl.amount - v_paid;
  if v_outstanding < 0 then
    raise exception 'negative outstanding forbidden';
  end if;

  update public.tax_obligations
  set status = case
      when v_outstanding = 0 then 'PAID'::public.tax_obligation_status
      when v_paid > 0 then 'PARTIALLY_PAID'::public.tax_obligation_status
      else 'OPEN'::public.tax_obligation_status
    end,
    updated_at = timezone('utc', now())
  where id = v_obl.id;

  return v_id;
end;

declare
  v_sub numeric(19, 4);
  v_disc numeric(19, 4);
  v_total numeric(19, 4);
begin
  select
    coalesce(sum(line_subtotal), 0),
    coalesce(sum(line_subtotal - line_total), 0),
    coalesce(sum(line_total), 0)
  into v_sub, v_disc, v_total
  from public.sales_document_lines
  where sales_document_id = p_document_id;

  update public.sales_documents
  set subtotal = v_sub, discount_total = v_disc, total = v_total
  where id = p_document_id;
end;

declare
  v_uid uuid;
  v_id uuid;
begin
  v_uid := public.tax_assert_role(
    p_organization_id,
    array['owner','admin','accountant','manager']::public.member_role[]
  );
  perform public.tax_assert_feature(p_organization_id);
  insert into public.tax_withholdings_perceptions (
    organization_id, counterparty_id, wp_type, tax_code, jurisdiction_code,
    certificate_number, operation_date, tax_period_date, amount, status, created_by
  ) values (
    p_organization_id, p_counterparty_id, p_wp_type, p_tax_code, p_jurisdiction_code,
    p_certificate_number, p_operation_date, p_tax_period_date, p_amount, 'CONFIRMED', v_uid
  )
  returning id into v_id;
  return v_id;
exception
  when unique_violation then
    raise exception 'duplicate withholding/perception certificate';
end;

declare
  v_uid uuid := auth.uid();
  v_doc public.sales_documents;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  select * into v_doc from public.sales_documents where id = p_document_id for update;
  if v_doc.document_type <> 'QUOTE' then raise exception 'not a quote'; end if;
  perform public.sales_assert_role(v_doc.organization_id, array['owner','admin','manager']::public.member_role[]);
  perform public.sales_assert_feature(v_doc.organization_id);
  if v_doc.status not in ('SENT', 'ACCEPTED') then raise exception 'quote cannot be rejected from this status'; end if;
  perform set_config('sales.engine_write', '1', true);
  update public.sales_documents
  set status = 'REJECTED', cancelled_at = timezone('utc', now()), cancel_reason = nullif(trim(p_reason), '')
  where id = p_document_id returning * into v_doc;
  perform set_config('sales.engine_write', '0', true);
  perform public.sales_write_audit(v_doc.organization_id, v_uid, 'sales.quote.rejected', v_doc.id, 'reject', '{}'::jsonb);
  return v_doc;
end;

declare
  v_uid uuid := auth.uid();
  v_res public.inventory_reservations%rowtype;
  v_remain numeric(18,4);
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  perform set_config('inventory.engine_write', '1', true);
  select * into v_res from public.inventory_reservations where id = p_reservation_id for update;
  if not found then raise exception 'reservation not found'; end if;
  if not public.is_org_member(v_res.organization_id) then raise exception 'not a member'; end if;
  perform public.inventory_assert_feature(v_res.organization_id);
  if v_res.status is distinct from 'ACTIVE' then return; end if;

  v_remain := v_res.quantity_reserved - v_res.quantity_consumed;
  update public.inventory_stock_state
  set reserved_quantity = reserved_quantity - v_remain,
      updated_at = timezone('utc', now())
  where organization_id = v_res.organization_id
    and warehouse_id = v_res.warehouse_id
    and product_id = v_res.product_id;

  update public.inventory_reservations
  set status = 'RELEASED', updated_at = timezone('utc', now())
  where id = p_reservation_id;
end;

declare
  v_uid uuid := (select auth.uid());
  v_period public.accounting_periods;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;

  if p_reason is null or char_length(trim(p_reason)) < 3 then
    raise exception 'reopen reason is required';
  end if;

  select * into v_period from public.accounting_periods where id = p_period_id for update;
  if not found then raise exception 'period not found'; end if;

  -- Privileged: owner/admin only (accountant may close but reopen is exceptional)
  if not public.has_org_role(
    v_period.organization_id,
    array['owner','admin']::public.member_role[]
  ) then
    raise exception 'insufficient role to reopen period';
  end if;

  if v_period.status <> 'CLOSED' then
    raise exception 'period is not closed';
  end if;

  -- Fiscal year must still be OPEN
  if exists (
    select 1 from public.accounting_fiscal_years
    where id = v_period.fiscal_year_id and status = 'CLOSED'
  ) then
    raise exception 'cannot reopen period in a CLOSED fiscal year';
  end if;

  update public.accounting_periods
  set
    status = 'OPEN',
    reopened_by = v_uid,
    reopened_at = timezone('utc', now()),
    reopen_reason = trim(p_reason),
    closed_at = null,
    closed_by = null
  where id = p_period_id
  returning * into v_period;

  perform public.accounting_write_audit(
    v_period.organization_id, v_uid, 'period.reopened', 'accounting_period',
    v_period.id::text, 'reopen',
    jsonb_build_object('name', v_period.name, 'reason', trim(p_reason))
  );

  return v_period;
end;

declare
  v_uid uuid;
  v_period public.tax_periods%rowtype;
begin
  if p_reason is null or length(trim(p_reason)) < 3 then
    raise exception 'reopen reason mandatory';
  end if;
  select * into v_period from public.tax_periods where id = p_tax_period_id for update;
  if not found then raise exception 'tax period not found'; end if;
  v_uid := public.tax_assert_role(
    v_period.organization_id,
    array['owner','accountant']::public.member_role[]
  );
  perform public.tax_assert_feature(v_period.organization_id);
  if v_period.status is distinct from 'CLOSED' then
    raise exception 'only CLOSED periods can be reopened';
  end if;

  perform set_config('tax.engine_write', '1', true);
  update public.tax_periods
  set status = 'REOPENED',
      reopen_reason = p_reason,
      reopened_by = v_uid,
      reopened_at = timezone('utc', now())
  where id = v_period.id;
end;

declare
  v_uid  uuid := auth.uid();
  v_sale public.pos_sales%rowtype;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;

  select * into v_sale
  from public.pos_sales
  where id = p_pos_sale_id;

  if not found then raise exception 'POS sale not found'; end if;

  if not public.has_org_role(
    v_sale.organization_id,
    array['owner','admin','manager','operator']::public.member_role[]
  ) then
    raise exception 'insufficient role to reset POS checkout';
  end if;

  if v_sale.status <> 'STOCK_RESERVED' then
    raise exception 'reset_pos_checkout only allowed in STOCK_RESERVED (got %)', v_sale.status;
  end if;

  -- Delegate: releases reservations + cancels sales doc + sets pos CANCELLED
  return public.cancel_pos_sale_draft(p_pos_sale_id, 'checkout reset by operator');
end;

declare v_id uuid;
begin
  select adjustment_offset_account_id into v_id
  from public.treasury_accounting_mappings where organization_id = p_org_id;
  if v_id is null then
    raise exception 'Falta configurar la cuenta contrapartida de ajustes de tesorería';
  end if;
  return v_id;
end;

declare v_id uuid;
begin
  select accounts_payable_account_id into v_id
  from public.treasury_accounting_mappings where organization_id = p_org_id;
  if v_id is null then
    select accounts_payable_account_id into v_id
    from public.purchase_accounting_mappings where organization_id = p_org_id;
  end if;
  if v_id is null then
    select id into v_id from public.accounts
    where organization_id = p_org_id and system_role = 'payables' and is_postable and is_active
    limit 1;
  end if;
  if v_id is null then raise exception 'Falta cuenta contable de proveedores'; end if;
  return v_id;
end;

declare v_id uuid;
begin
  select accounts_receivable_account_id into v_id
  from public.treasury_accounting_mappings where organization_id = p_org_id;
  if v_id is null then
    select receivables_account_id into v_id
    from public.fiscal_accounting_mappings where organization_id = p_org_id;
  end if;
  if v_id is null then
    select id into v_id from public.accounts
    where organization_id = p_org_id and system_role = 'receivables' and is_postable and is_active
    limit 1;
  end if;
  if v_id is null then raise exception 'Falta cuenta contable de clientes'; end if;
  return v_id;
end;

declare
  v_id uuid;
begin
  select id into v_id
  from public.fiscal_rule_versions
  where status = 'ACTIVE'
    and effective_from <= p_issue_date
    and (effective_to is null or effective_to >= p_issue_date)
    and (organization_id = p_org_id or organization_id is null)
  order by
    case when organization_id = p_org_id then 0 else 1 end,
    effective_from desc,
    version desc
  limit 1;

  if v_id is null then
    raise exception 'no ACTIVE fiscal rule version for issue_date %', p_issue_date;
  end if;
  return v_id;
end;

declare v_id uuid;
begin
  select opening_equity_account_id into v_id
  from public.treasury_accounting_mappings where organization_id = p_org_id;
  if v_id is null then
    select id into v_id from public.accounts
    where organization_id = p_org_id and system_role = 'capital' and is_postable and is_active
    limit 1;
  end if;
  if v_id is null then raise exception 'Falta cuenta de patrimonio para saldo inicial'; end if;
  return v_id;
end;

declare
  v_period public.tax_periods%rowtype;
  v_det public.tax_determinations%rowtype;
  v_src public.tax_determination_sources%rowtype;
  v_fd public.fiscal_documents%rowtype;
  v_fts public.fiscal_tax_summaries%rowtype;
  v_pd public.purchase_documents%rowtype;
  v_pts public.purchase_document_tax_summaries%rowtype;
  v_cls public.vat_purchase_classifications%rowtype;
  v_new text;
  v_changed boolean := false;
begin
  select * into v_period from public.tax_periods where id = p_tax_period_id;
  if not found then raise exception 'tax period not found'; end if;
  if not public.is_org_member(v_period.organization_id) then
    raise exception 'not a member';
  end if;

  select * into v_det
  from public.tax_determinations
  where tax_period_id = p_tax_period_id and is_current
  limit 1;
  if not found then
    return 'NO_DETERMINATION';
  end if;

  for v_src in
    select * from public.tax_determination_sources
    where tax_determination_id = v_det.id
  loop
    if v_src.source_domain = 'FISCAL_DOCUMENT' then
      select * into v_fd from public.fiscal_documents where id = v_src.source_id;
      select * into v_fts from public.fiscal_tax_summaries where id = v_src.source_component_id;
      if found and v_fd.id is not null then
        v_new := public.tax_canonical_fiscal_hash(v_fd, v_fts);
        if v_new is distinct from v_src.canonical_source_hash then
          v_changed := true;
        end if;
      else
        v_changed := true;
      end if;
    elsif v_src.source_domain = 'PURCHASE_DOCUMENT' then
      select * into v_pd from public.purchase_documents where id = v_src.source_id;
      select * into v_pts from public.purchase_document_tax_summaries where id = v_src.source_component_id;
      select * into v_cls from public.vat_purchase_classifications where id = v_src.classification_id;
      if v_pd.id is not null and v_pts.id is not null and v_cls.id is not null then
        v_new := public.tax_canonical_purchase_hash(v_pd, v_pts, v_cls);
        if v_new is distinct from v_src.canonical_source_hash then
          v_changed := true;
        end if;
      else
        v_changed := true;
      end if;
    end if;
  end loop;

  if v_changed and v_det.status in ('REVIEWED', 'CALCULATED') then
    perform set_config('tax.engine_write', '1', true);
    update public.tax_determinations
    set status = 'STALE',
        stale_detected_at = timezone('utc', now()),
        stale_reason = 'Los datos fuente cambiaron desde la última revisión.'
    where id = v_det.id;
    update public.tax_periods
    set source_changed = true
    where id = v_period.id;
    return 'SOURCE_CHANGED';
  end if;

  if v_changed then
    return 'SOURCE_CHANGED';
  end if;
  return 'OK';
end;

declare
  v_uid uuid := auth.uid();
  v_op public.inventory_operations%rowtype;
  v_line record;
  v_later int;
  v_rev_id uuid;
  v_num text;
  v_cost public.inventory_cost_state%rowtype;
  v_q1 numeric(18,4);
  v_v1 numeric(19,4);
  v_avg numeric(19,6);
  v_rev_line_no int := 0;
  v_new_line uuid;
  v_sum_wh numeric(18,4);
  v_prod uuid;
  v_period_id uuid;
  v_rev_journal uuid;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then
    raise exception 'reversal reason required';
  end if;

  select * into v_op from public.inventory_operations where id = p_operation_id for update;
  if not found then raise exception 'operation not found'; end if;
  if v_op.status is distinct from 'POSTED' then
    raise exception 'only POSTED operations can be reversed';
  end if;

  perform public.inventory_assert_feature(v_op.organization_id);
  if not public.has_org_role(
    v_op.organization_id, array['owner','admin','accountant']::public.member_role[]
  ) then
    raise exception 'insufficient role to reverse';
  end if;

  select period_id into v_period_id
  from public.resolve_open_period(v_op.organization_id, p_reversal_date);
  if v_period_id is null then
    raise exception 'ACCOUNTING_REQUIRES_REVIEW: accounting period is closed';
  end if;

  -- Receipt reversal safety: no later valuation movements for product
  if v_op.operation_type = 'RECEIPT' then
    for v_prod in
      select distinct product_id from public.inventory_operation_lines
      where inventory_operation_id = p_operation_id order by 1
    loop
      select count(*) into v_later
      from public.inventory_ledger_entries le
      where le.organization_id = v_op.organization_id
        and le.product_id = v_prod
        and le.inventory_operation_id is distinct from p_operation_id
        and (
          le.movement_date > v_op.operation_date
          or (le.movement_date = v_op.operation_date and le.created_at > (
            select posted_at from public.inventory_operations where id = p_operation_id
          ))
        )
        and le.operation_type in (
          'RECEIPT','ISSUE','RETURN_TO_SUPPLIER','ADJUSTMENT_IN','ADJUSTMENT_OUT'
        );
      if v_later > 0 then
        raise exception 'INVENTORY_REQUIRES_REVIEW: receipt reversal unsafe after later valuation movements';
      end if;
    end loop;
  end if;

  perform set_config('inventory.engine_write', '1', true);

  v_num := public.next_inventory_operation_number(v_op.organization_id, 'REVERSAL');

  insert into public.inventory_operations (
    organization_id, internal_number, operation_type, status, accounting_status,
    operation_date, warehouse_id, destination_warehouse_id, counterparty_id,
    reversed_operation_id, reason, description, idempotency_key, created_by
  ) values (
    v_op.organization_id, v_num, 'REVERSAL', 'DRAFT', 'PENDING',
    p_reversal_date, v_op.warehouse_id, v_op.destination_warehouse_id, v_op.counterparty_id,
    p_operation_id, p_reason, 'Reversión de ' || v_op.internal_number,
    'rev-' || p_operation_id::text, v_uid
  )
  returning id into v_rev_id;

  -- Lock products
  for v_prod in
    select distinct product_id from public.inventory_operation_lines
    where inventory_operation_id = p_operation_id order by 1
  loop
    perform public.ensure_inventory_cost_row(v_op.organization_id, v_prod);
    perform 1 from public.inventory_cost_state
    where organization_id = v_op.organization_id and product_id = v_prod for update;
  end loop;

  for v_line in
    select * from public.inventory_operation_lines
    where inventory_operation_id = p_operation_id
    order by line_number
  loop
    perform public.ensure_inventory_stock_row(v_op.organization_id, v_line.warehouse_id, v_line.product_id);
    perform 1 from public.inventory_stock_state
    where organization_id = v_op.organization_id
      and warehouse_id = v_line.warehouse_id and product_id = v_line.product_id
    for update;

    select * into v_cost from public.inventory_cost_state
    where organization_id = v_op.organization_id and product_id = v_line.product_id;

    v_rev_line_no := v_rev_line_no + 1;

    if v_line.direction = 'IN' then
      -- reverse IN => OUT at original cost
      if exists (
        select 1 from public.inventory_stock_state
        where organization_id = v_op.organization_id
          and warehouse_id = v_line.warehouse_id and product_id = v_line.product_id
          and on_hand_quantity < v_line.quantity
      ) then
        raise exception 'INVENTORY_REQUIRES_REVIEW: cannot reverse IN — stock consumed';
      end if;

      v_q1 := v_cost.quantity_on_hand_total - v_line.quantity;
      v_v1 := v_cost.inventory_value - v_line.value_delta;
      if v_q1 = 0 then v_v1 := 0; v_avg := 0;
      else v_avg := public.inventory_round_avg(v_v1, v_q1); end if;

      if v_op.operation_type is distinct from 'TRANSFER' then
        update public.inventory_cost_state
        set quantity_on_hand_total = v_q1, inventory_value = v_v1, average_unit_cost = v_avg,
            updated_at = timezone('utc', now())
        where organization_id = v_op.organization_id and product_id = v_line.product_id;
      end if;

      update public.inventory_stock_state
      set on_hand_quantity = on_hand_quantity - v_line.quantity, updated_at = timezone('utc', now())
      where organization_id = v_op.organization_id
        and warehouse_id = v_line.warehouse_id and product_id = v_line.product_id
        and on_hand_quantity >= v_line.quantity;

      insert into public.inventory_operation_lines (
        organization_id, inventory_operation_id, line_number, product_id, warehouse_id,
        direction, quantity, unit_code, unit_cost, value_delta
      ) values (
        v_op.organization_id, v_rev_id, v_rev_line_no, v_line.product_id, v_line.warehouse_id,
        'OUT', v_line.quantity, v_line.unit_code, v_line.unit_cost, v_line.value_delta
      ) returning id into v_new_line;

      insert into public.inventory_ledger_entries (
        organization_id, inventory_operation_id, inventory_operation_line_id,
        product_id, warehouse_id, movement_date, operation_type, direction,
        quantity, unit_cost, value_delta, source_type, source_id
      ) values (
        v_op.organization_id, v_rev_id, v_new_line,
        v_line.product_id, v_line.warehouse_id, p_reversal_date, 'REVERSAL', 'OUT',
        v_line.quantity, v_line.unit_cost, v_line.value_delta, 'INVENTORY_OPERATION', v_rev_id
      );

    else
      -- reverse OUT => IN at original snapshotted cost
      v_q1 := v_cost.quantity_on_hand_total + v_line.quantity;
      v_v1 := v_cost.inventory_value + v_line.value_delta;
      v_avg := public.inventory_round_avg(v_v1, v_q1);

      if v_op.operation_type is distinct from 'TRANSFER' then
        update public.inventory_cost_state
        set quantity_on_hand_total = v_q1, inventory_value = v_v1, average_unit_cost = v_avg,
            updated_at = timezone('utc', now())
        where organization_id = v_op.organization_id and product_id = v_line.product_id;
      end if;

      update public.inventory_stock_state
      set on_hand_quantity = on_hand_quantity + v_line.quantity, updated_at = timezone('utc', now())
      where organization_id = v_op.organization_id
        and warehouse_id = v_line.warehouse_id and product_id = v_line.product_id;

      insert into public.inventory_operation_lines (
        organization_id, inventory_operation_id, line_number, product_id, warehouse_id,
        direction, quantity, unit_code, unit_cost, value_delta
      ) values (
        v_op.organization_id, v_rev_id, v_rev_line_no, v_line.product_id, v_line.warehouse_id,
        'IN', v_line.quantity, v_line.unit_code, v_line.unit_cost, v_line.value_delta
      ) returning id into v_new_line;

      insert into public.inventory_ledger_entries (
        organization_id, inventory_operation_id, inventory_operation_line_id,
        product_id, warehouse_id, movement_date, operation_type, direction,
        quantity, unit_cost, value_delta, source_type, source_id
      ) values (
        v_op.organization_id, v_rev_id, v_new_line,
        v_line.product_id, v_line.warehouse_id, p_reversal_date, 'REVERSAL', 'IN',
        v_line.quantity, v_line.unit_cost, v_line.value_delta, 'INVENTORY_OPERATION', v_rev_id
      );
    end if;
  end loop;

  for v_prod in
    select distinct product_id from public.inventory_operation_lines
    where inventory_operation_id = p_operation_id order by 1
  loop
    select coalesce(sum(on_hand_quantity),0) into v_sum_wh
    from public.inventory_stock_state
    where organization_id = v_op.organization_id and product_id = v_prod;
    select quantity_on_hand_total into v_q1 from public.inventory_cost_state
    where organization_id = v_op.organization_id and product_id = v_prod;
    if v_op.operation_type is distinct from 'TRANSFER' and v_sum_wh is distinct from v_q1 then
      raise exception 'reversal reconciliation failed';
    end if;
  end loop;

  -- Accounting reverse
  if v_op.journal_entry_id is not null then
    v_rev_journal := (public.reverse_journal_entry(v_op.journal_entry_id, p_reversal_date, p_reason)).id;
  end if;

  update public.inventory_operations
  set status = 'POSTED',
      accounting_status = case when v_op.journal_entry_id is null then 'NOT_APPLICABLE' else 'POSTED' end,
      journal_entry_id = v_rev_journal,
      posted_by = v_uid, posted_at = timezone('utc', now()),
      updated_at = timezone('utc', now())
  where id = v_rev_id;

  update public.inventory_operations
  set status = 'REVERSED',
      reverse_journal_entry_id = v_rev_journal,
      reversed_by = v_uid,
      reversed_at = timezone('utc', now()),
      updated_at = timezone('utc', now())
  where id = p_operation_id;

  return v_rev_id;
end;

declare
  v_uid uuid := (select auth.uid());
  v_orig public.journal_entries;
  v_rev public.journal_entries;
  v_period_id uuid;
  v_fy_id uuid;
  v_number text;
  v_debit numeric(19,4);
  v_credit numeric(19,4);
  v_line_count int;
  r record;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  if p_reason is null or char_length(trim(p_reason)) < 3 then
    raise exception 'reversal reason is required';
  end if;

  select * into v_orig
  from public.journal_entries
  where id = p_original_entry_id
  for update;

  if not found then
    raise exception 'journal entry not found';
  end if;

  if not public.is_org_member(v_orig.organization_id) then
    raise exception 'not a member of organization';
  end if;

  if not public.has_org_role(
    v_orig.organization_id,
    array['owner','admin','accountant']::public.member_role[]
  ) then
    raise exception 'insufficient role to reverse journal entries';
  end if;

  if v_orig.status <> 'POSTED' then
    raise exception 'only POSTED entries can be reversed';
  end if;

  if v_orig.reversed_by_entry_id is not null then
    raise exception 'entry already reversed';
  end if;

  select period_id, fiscal_year_id into v_period_id, v_fy_id
  from public.resolve_open_period(v_orig.organization_id, p_reversal_date);

  if v_period_id is null then
    raise exception 'no OPEN period (and OPEN fiscal year) covers reversal_date';
  end if;

  perform set_config('accounting.engine_write', '1', true);

  insert into public.journal_entries (
    organization_id,
    fiscal_year_id,
    period_id,
    entry_date,
    description,
    status,
    source_type,
    source_id,
    external_reference,
    reversal_of_entry_id,
    reversal_reason,
    created_by
  ) values (
    v_orig.organization_id,
    v_fy_id,
    v_period_id,
    p_reversal_date,
    'Reversión de asiento ' || coalesce(v_orig.entry_number, v_orig.id::text) || ': ' || v_orig.description,
    'DRAFT',
    'SYSTEM',
    v_orig.id,
    v_orig.external_reference,
    v_orig.id,
    trim(p_reason),
    v_uid
  )
  returning * into v_rev;

  for r in
    select * from public.journal_entry_lines
    where journal_entry_id = v_orig.id
    order by line_number
  loop
    insert into public.journal_entry_lines (
      journal_entry_id,
      organization_id,
      account_id,
      cost_center_id,
      counterparty_id,
      description,
      debit,
      credit,
      line_number,
      metadata
    ) values (
      v_rev.id,
      r.organization_id,
      r.account_id,
      r.cost_center_id,
      r.counterparty_id,
      coalesce(r.description, 'Reversión'),
      r.credit,
      r.debit,
      r.line_number,
      coalesce(r.metadata, '{}'::jsonb) || jsonb_build_object('reversed_from_line_id', r.id)
    );
  end loop;

  select count(*)::int, coalesce(sum(debit), 0), coalesce(sum(credit), 0)
  into v_line_count, v_debit, v_credit
  from public.journal_entry_lines
  where journal_entry_id = v_rev.id;

  if v_line_count < 2 or v_debit <> v_credit or v_debit <= 0 then
    raise exception 'reversal entry failed balance validation';
  end if;

  v_number := public.next_journal_entry_number(v_orig.organization_id, v_fy_id);

  update public.journal_entries
  set
    status = 'POSTED',
    entry_number = v_number,
    posted_by = v_uid,
    posted_at = timezone('utc', now())
  where id = v_rev.id
  returning * into v_rev;

  update public.journal_entries
  set
    status = 'REVERSED',
    reversed_by_entry_id = v_rev.id
  where id = v_orig.id;

  perform set_config('accounting.engine_write', '0', true);

  perform public.accounting_write_audit(
    v_orig.organization_id,
    v_uid,
    'journal.reversed',
    'journal_entry',
    v_orig.id::text,
    'reverse',
    jsonb_build_object(
      'original_entry_number', v_orig.entry_number,
      'reversal_entry_id', v_rev.id,
      'reversal_entry_number', v_rev.entry_number,
      'reason', trim(p_reason)
    )
  );

  return v_rev;
end;

declare
  v_doc public.purchase_documents%rowtype;
  v_rev public.journal_entries%rowtype;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  select * into v_doc from public.purchase_documents where id = p_document_id for update;
  if not found then raise exception 'purchase document not found'; end if;
  perform public.purchase_assert_feature(v_doc.organization_id);
  perform public.purchase_assert_role(
    v_doc.organization_id,
    array['owner','admin','accountant']::public.member_role[]
  );

  if v_doc.status = 'REVERSED' then
    return p_document_id; -- idempotent
  end if;
  if v_doc.status is distinct from 'POSTED' or v_doc.journal_entry_id is null then
    raise exception 'only POSTED purchases with journal can be reversed';
  end if;

  select * into v_rev from public.reverse_journal_entry(
    v_doc.journal_entry_id, p_reversal_date, coalesce(p_reason, 'Reversión compra')
  );

  perform set_config('purchase.engine_write', '1', true);

  update public.purchase_documents
  set status = 'REVERSED',
      reverse_journal_entry_id = v_rev.id,
      accounting_status = 'POSTED',
      updated_at = timezone('utc', now())
  where id = p_document_id;

  update public.accounts_payable_items
  set status = 'VOID',
      open_amount = 0,
      updated_at = timezone('utc', now())
  where purchase_document_id = p_document_id;

  return p_document_id;
end;

declare
  v_uid uuid := auth.uid();
  v_op public.treasury_operations%rowtype;
  v_rev public.journal_entries%rowtype;
  v_alloc record;
begin
  if v_uid is null then raise exception 'authentication required'; end if;
  if p_reason is null or char_length(trim(p_reason)) < 3 then
    raise exception 'reversal reason is required';
  end if;

  select * into v_op from public.treasury_operations where id = p_operation_id for update;
  if not found then raise exception 'treasury operation not found'; end if;

  perform public.treasury_assert_feature(v_op.organization_id, array['cash','banks']);

  if v_op.operation_type = 'ADJUSTMENT' then
    if not public.has_org_role(
      v_op.organization_id, array['owner','accountant']::public.member_role[]
    ) then
      raise exception 'only owner/accountant may reverse adjustments';
    end if;
  else
    if not public.has_org_role(
      v_op.organization_id, array['owner','admin','accountant']::public.member_role[]
    ) then
      raise exception 'insufficient role to reverse treasury operation';
    end if;
  end if;

  if v_op.status = 'REVERSED' then
    return p_operation_id;
  end if;
  if v_op.status is distinct from 'POSTED' or v_op.journal_entry_id is null then
    raise exception 'only POSTED operations with journal can be reversed';
  end if;

  -- Lock open items before restore
  if v_op.operation_type = 'PAYMENT' then
    perform 1 from public.accounts_payable_items ap
    where ap.id in (
      select accounts_payable_item_id from public.payment_allocations
      where treasury_operation_id = p_operation_id
    )
    order by ap.id for update;
  elsif v_op.operation_type = 'COLLECTION' then
    perform 1 from public.accounts_receivable_items ar
    where ar.id in (
      select accounts_receivable_item_id from public.collection_allocations
      where treasury_operation_id = p_operation_id
    )
    order by ar.id for update;
  end if;

  select * into v_rev from public.reverse_journal_entry(
    v_op.journal_entry_id, p_reversal_date, trim(p_reason)
  );

  perform set_config('treasury.engine_write', '1', true);

  if v_op.operation_type = 'PAYMENT' then
    for v_alloc in
      select * from public.payment_allocations
      where treasury_operation_id = p_operation_id
      order by accounts_payable_item_id
    loop
      update public.accounts_payable_items
      set open_amount = open_amount + v_alloc.allocated_amount,
          status = case
            when open_amount + v_alloc.allocated_amount >= original_amount
              then 'OPEN'::public.accounts_payable_status
            else 'PARTIALLY_PAID'::public.accounts_payable_status
          end,
          updated_at = timezone('utc', now())
      where id = v_alloc.accounts_payable_item_id;
    end loop;
  elsif v_op.operation_type = 'COLLECTION' then
    for v_alloc in
      select * from public.collection_allocations
      where treasury_operation_id = p_operation_id
      order by accounts_receivable_item_id
    loop
      update public.accounts_receivable_items
      set open_amount = open_amount + v_alloc.allocated_amount,
          status = case
            when open_amount + v_alloc.allocated_amount >= original_amount
              then 'OPEN'::public.accounts_receivable_status
            else 'PARTIALLY_COLLECTED'::public.accounts_receivable_status
          end,
          updated_at = timezone('utc', now())
      where id = v_alloc.accounts_receivable_item_id;
    end loop;
  end if;

  -- Domain status REVERSED; original journal stays REVERSED in Phase 2 with reversal pair
  update public.treasury_operations
  set status = 'REVERSED',
      reverse_journal_entry_id = v_rev.id,
      reversed_by = v_uid,
      reversed_at = timezone('utc', now()),
      reason = coalesce(reason, trim(p_reason)),
      updated_at = timezone('utc', now())
  where id = p_operation_id;

  return p_operation_id;
end;

declare
  v_uid uuid;
  v_period public.tax_periods%rowtype;
  v_det public.tax_determinations%rowtype;
  v_reval text;
begin
  select * into v_period from public.tax_periods where id = p_tax_period_id for update;
  if not found then raise exception 'tax period not found'; end if;

  v_uid := public.tax_assert_role(
    v_period.organization_id,
    array['owner','accountant']::public.member_role[]
  );
  perform public.tax_assert_feature(v_period.organization_id);

  select * into v_det from public.tax_determinations
  where tax_period_id = p_tax_period_id and is_current;
  if not found then raise exception 'calculate determination first'; end if;
  if v_det.status = 'REVIEW_REQUIRED' then
    raise exception 'unresolved REVIEW_REQUIRED items remain';
  end if;
  if v_det.status = 'STALE' then
    raise exception 'SOURCE_CHANGED — recalculate after reopen if closed';
  end if;

  v_reval := public.revalidate_tax_determination_sources(p_tax_period_id);
  if v_reval = 'SOURCE_CHANGED' then
    raise exception 'Los datos fuente cambiaron desde la última revisión.';
  end if;

  perform set_config('tax.engine_write', '1', true);
  update public.tax_determinations
  set status = 'REVIEWED', reviewed_by = v_uid, reviewed_at = timezone('utc', now())
  where id = v_det.id;
  update public.tax_periods
  set status = 'REVIEWED', reviewed_by = v_uid, reviewed_at = timezone('utc', now()), source_changed = false
  where id = v_period.id;
end;

