  insert into public.fiscal_tax_summaries (
    organization_id, fiscal_document_id, summary_kind, code, base_amount, rate, amount
  ) values (
    p_organization_id, v_doc_id, 'IVA', '5', v_net, 21.0000, p_vat_amount
  );

  return v_doc_id;
